76|export function mapAgentPackTools(value: unknown): AgentPackToolMapping {
77|	const values = Array.isArray(value) ? value : typeof value === "string" ? value.split(",") : [];
78|	const tools = new Set<string>();
79|	const unsupported = new Set<string>();
80|	for (const value of values) {
81|		if (typeof value !== "string" || !value.trim()) continue;
82|		switch (normalizeToolToken(value)) {
83|			case "read":
84|			case "read_file":
85|				tools.add("read");
86|				break;
87|			case "grep":
88|			case "search":
89|			case "search_files":
90|				tools.add("grep");
