74|export function createPiMcpSubagentAdapter(options: {
75|	agentDir: string;
76|	getParentSession: () => AgentSession | undefined;
77|}): IceSubagentMcpAdapter {
78|	return {
79|		listAuthorizedTools: () => listPiMcpAuthorizedTools(options.agentDir),
80|		async dispatch(server, tool, params, signal) {
81|			const proxy = options.getParentSession()?.getRegisteredTool("mcp");
82|			if (!proxy) throw new Error("The parent session has no active MCP proxy tool.");
83|			return proxy.execute(`subagent-mcp-${randomUUID()}`, { server, tool, args: params }, signal);
84|		},
