60|function schemaDiagnostics(schema: TSchema, value: unknown): string[] {
61|	const out: string[] = [];
62|	for (const error of Value.Errors(schema, value)) {
63|		const unknownKey = error.keyword === "additionalProperties" ? unknownKeysOf(error) : [];
64|		if (unknownKey.length > 0) {
65|			for (const key of unknownKey) {
66|				const replacement = LEGACY_AGENT_KEY_REPLACEMENTS[key];
