133|export function resolveCommandOnPath(command: string, environment: NodeJS.ProcessEnv): string | undefined {
134|	if (!SAFE_COMMAND_NAME_PATTERN.test(command)) return undefined;
135|	const pathVariable = environment.PATH ?? "";
136|	const directories = pathVariable.split(sep === "\\" ? ";" : ":").filter((entry) => entry.length > 0);
137|	for (const directory of directories) {
138|		const candidate = resolve(directory, command);
139|		try {
140|			accessSync(candidate, constants.X_OK);
141|			if (!statSync(candidate).isFile()) continue;
142|			return candidate;
143|		} catch {}
144|	}
145|	return undefined;
146|}
