14|export function formatAgentDefinitions(source: { definitions(): LoadedAgentDefinitions }): string {
15|	const definitions = source.definitions();
16|	const lines = [...definitions.active.values()].map(
17|		(definition) =>
18|			`${definition.name} [${definition.source}${definition.limited ? ", limited" : ""}${definition.fields.hidden ? ", hidden" : ""}]: ${definition.description}${definition.diagnostics.length ? ` (${definition.diagnostics.join("; ")})` : ""}`,
19|	);
20|	for (const entry of definitions.shadowed)
21|		lines.push(`${entry.definition.name} [${entry.definition.source}] shadowed by ${entry.shadowedBy.source}`);
22|	for (const definition of definitions.disabled) lines.push(`${definition.name} [disabled]`);
23|	for (const issue of definitions.issues)
24|		lines.push(
25|			`${issue.name ?? "(unnamed)"} [${issue.availability}] ${issue.sourcePath ?? ""}: ${issue.diagnostics.join("; ")}`,
26|		);
27|	return lines.join("\n");
