148|	const describe = (folder: PruneFolder) =>
149|		`  ${folder.path} (${folder.transcripts} transcript${folder.transcripts === 1 ? "" : "s"}, ${folder.worktrees} worktree${folder.worktrees === 1 ? "" : "s"})`;
150|	const lines: string[] = [];
151|	if (removed.length > 0)
152|		lines.push(result.applied ? "Removed:" : "Would remove (run with --apply to delete):", ...removed.map(describe));
153|	if (kept.length > 0)
154|		lines.push(
155|			"Kept:",
156|			...kept.flatMap((folder) => [describe(folder), ...folder.reasons.map((reason) => `    - ${reason}`)]),
157|		);
158|	return lines.join("\n");

