299|export function boundedText(text: string, limit: number): { text: string; truncated: boolean } {
300|	if (Buffer.byteLength(text) <= limit) return { text, truncated: false };
301|	const marker = "\n[truncated]";
302|	let end = Math.max(0, limit - Buffer.byteLength(marker));
303|	const bytes = Buffer.from(text);
304|	while (end > 0 && (bytes[end]! & 0xc0) === 0x80) end--;
305|	return { text: `${bytes.subarray(0, end).toString("utf8")}${marker}`, truncated: true };
