457|export function normalizePlainFinalAnswer(text: string): string {
458|	const parsed = parseSubagentReportOutcome(text, Number.MAX_SAFE_INTEGER);
459|	if (parsed.kind !== "valid") return text;
460|	const reportedPaths = parsed.report.paths.map((path) => `- ${redactCredentialText(path)}`).join("\n");
461|	const reportedFindings = parsed.report.findings
462|		.map(
463|			(finding) =>
464|				`- [${finding.severity}] ${redactCredentialText(finding.category)}: ${redactCredentialText(finding.claim)}`,
465|		)
466|		.join("\n");
467|	return [
468|		redactCredentialText(parsed.report.summary),
469|		reportedPaths ? `Reported paths (not independently verified):\n${reportedPaths}` : undefined,
470|		reportedFindings ? `Reported findings (not independently verified):\n${reportedFindings}` : undefined,
471|	]
472|		.filter((part): part is string => part !== undefined)
473|		.join("\n\n");
