319|export function backfillSubagentUsage(
320|	registry: ChildRegistry<ResidentChild>,
321|	journal: ParentJournal,
322|	ownerSessionId: string,
323|): void {
324|	const covered = new Map<
325|		string,
326|		{ input: number; output: number; cacheRead: number; cacheWrite: number; cost: number }
327|	>();
328|	for (const entry of journal.entries()) {
329|		if (entry.customType !== "subagent_usage") continue;
330|		const data = entry.data as { childId?: unknown; usage?: Record<string, unknown> } | undefined;
331|		if (typeof data?.childId !== "string" || !data.usage) continue;
332|		const sum = covered.get(data.childId) ?? { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0 };
333|		for (const key of ["input", "output", "cacheRead", "cacheWrite", "cost"] as const) {
334|			const value = data.usage[key];
335|			if (typeof value === "number" && Number.isFinite(value)) sum[key] += value;
336|		}
337|		covered.set(data.childId, sum);
338|	}
339|	let appended = false;
340|	for (const record of registry.list(ownerSessionId, { includeDeleted: true })) {
341|		const sum = covered.get(record.id) ?? { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0 };
342|		const usage = {
343|			input: Math.max(0, record.usage.inputTokens - sum.input),
344|			output: Math.max(0, record.usage.outputTokens - sum.output),
345|			cacheRead: Math.max(0, (record.usage.cacheReadTokens ?? 0) - sum.cacheRead),
346|			cacheWrite: Math.max(0, (record.usage.cacheWriteTokens ?? 0) - sum.cacheWrite),
347|			// Sub-micro-dollar remainders are float noise, not missing billing.
348|			cost: record.usage.cost - sum.cost > 1e-9 ? record.usage.cost - sum.cost : 0,
349|		};
350|		if (!usage.input && !usage.output && !usage.cacheRead && !usage.cacheWrite && !usage.cost) continue;
351|		journal.append("subagent_usage", { childId: record.id, agent: record.agent, usage, backfill: true });
352|		appended = true;
353|	}
354|	if (appended) journal.flush();
